{
  "name": "block-isle",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "^6.0.0"
  }
}

// Block definitions, procedural pixel textures and the shared texture atlas.
import * as THREE from 'three';

export const BLOCK = {
  AIR: 0,
  GRASS: 1,
  DIRT: 2,
  STONE: 3,
  COBBLE: 4,
  SAND: 5,
  LOG: 6,
  LEAVES: 7,
  PLANKS: 8,
  GLASS: 9,
  BRICK: 10,
  SNOW: 11,
  GLOWSTONE: 12,
  WATER: 13,
  BEDROCK: 14,
  ROSE: 15,
  DAISY: 16,
  TALLGRASS: 17,
  STONEBRICK: 18,
};

export const TILE = 16;
export const ATLAS_COLS = 8;
export const ATLAS_ROWS = 4;
export const ATLAS_W = TILE * ATLAS_COLS;
export const ATLAS_H = TILE * ATLAS_ROWS;

// Tile ids inside the atlas.
const T = {
  grassTop: 0,
  grassSide: 1,
  dirt: 2,
  stone: 3,
  cobble: 4,
  sand: 5,
  logSide: 6,
  logTop: 7,
  leaves: 8,
  planks: 9,
  glass: 10,
  brick: 11,
  snow: 12,
  glow: 13,
  water: 14,
  bedrock: 15,
  rose: 16,
  daisy: 17,
  tallgrass: 18,
  stonebrick: 19,
  clouds: 20,
};

export const BLOCKS = [];
function def(id, name, tiles, opts = {}) {
  BLOCKS[id] = {
    id,
    name,
    tiles,
    solid: opts.solid ?? true,
    opaque: opts.opaque ?? true,
    breakable: opts.breakable ?? true,
    cross: opts.cross ?? false,
    liquid: opts.liquid ?? false,
    drop: opts.drop ?? id,
    color: opts.color ?? 0xffffff,
    luminous: opts.luminous ?? false,
  };
}

def(BLOCK.AIR, 'Air', null, { solid: false, opaque: false, breakable: false });
def(BLOCK.GRASS, 'Grass Block', { top: T.grassTop, side: T.grassSide, bottom: T.dirt }, { color: 0x7cb95b });
def(BLOCK.DIRT, 'Dirt', { top: T.dirt, side: T.dirt, bottom: T.dirt }, { color: 0x8b5e3c });
def(BLOCK.STONE, 'Stone', { top: T.stone, side: T.stone, bottom: T.stone }, { color: 0x8a8d91 });
def(BLOCK.COBBLE, 'Cobblestone', { top: T.cobble, side: T.cobble, bottom: T.cobble }, { color: 0x777b7e });
def(BLOCK.SAND, 'Sand', { top: T.sand, side: T.sand, bottom: T.sand }, { color: 0xe6d49b });
def(BLOCK.LOG, 'Oak Log', { top: T.logTop, side: T.logSide, bottom: T.logTop }, { color: 0x8a6134 });
def(BLOCK.LEAVES, 'Oak Leaves', { top: T.leaves, side: T.leaves, bottom: T.leaves }, { opaque: false, color: 0x3f7c34 });
def(BLOCK.PLANKS, 'Oak Planks', { top: T.planks, side: T.planks, bottom: T.planks }, { color: 0xb28a54 });
def(BLOCK.GLASS, 'Glass', { top: T.glass, side: T.glass, bottom: T.glass }, { opaque: false, color: 0xc9e9f3 });
def(BLOCK.BRICK, 'Bricks', { top: T.brick, side: T.brick, bottom: T.brick }, { color: 0xa44f3e });
def(BLOCK.SNOW, 'Snow', { top: T.snow, side: T.snow, bottom: T.snow }, { color: 0xeef4f7 });
def(BLOCK.GLOWSTONE, 'Glowstone', { top: T.glow, side: T.glow, bottom: T.glow }, { color: 0xffd47a, luminous: true });
def(BLOCK.WATER, 'Water', { top: T.water, side: T.water, bottom: T.water }, { solid: false, opaque: false, breakable: false, liquid: true, color: 0x3d7fd6 });
def(BLOCK.BEDROCK, 'Bedrock', { top: T.bedrock, side: T.bedrock, bottom: T.bedrock }, { breakable: false, color: 0x45484d });
def(BLOCK.ROSE, 'Rose', { top: T.rose, side: T.rose, bottom: T.rose }, { solid: false, opaque: false, cross: true, color: 0xcc3a4a });
def(BLOCK.DAISY, 'Daisy', { top: T.daisy, side: T.daisy, bottom: T.daisy }, { solid: false, opaque: false, cross: true, color: 0xf2d75e });
def(BLOCK.TALLGRASS, 'Tall Grass', { top: T.tallgrass, side: T.tallgrass, bottom: T.tallgrass }, { solid: false, opaque: false, cross: true, color: 0x67a847 });
def(BLOCK.STONEBRICK, 'Stone Bricks', { top: T.stonebrick, side: T.stonebrick, bottom: T.stonebrick }, { color: 0x8d9297 });

export const PLACEABLE = [
  BLOCK.GRASS, BLOCK.DIRT, BLOCK.STONE, BLOCK.COBBLE, BLOCK.SAND,
  BLOCK.LOG, BLOCK.LEAVES, BLOCK.PLANKS, BLOCK.GLASS, BLOCK.BRICK,
  BLOCK.SNOW, BLOCK.GLOWSTONE, BLOCK.STONEBRICK,
];

export const isOpaque = (id) => BLOCKS[id]?.opaque ?? false;
export const isSolid = (id) => BLOCKS[id]?.solid ?? false;
export const isCross = (id) => BLOCKS[id]?.cross ?? false;
export const isLiquid = (id) => BLOCKS[id]?.liquid ?? false;

// ---------------------------------------------------------------------------
// Pixel art generation
// ---------------------------------------------------------------------------
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rgb = (r, g, b, a = 255) => `rgba(${r | 0},${g | 0},${b | 0},${a / 255})`;

function fillNoise(ctx, x, y, base, spread, rand, count = 256) {
  for (let py = 0; py < TILE; py++) {
    for (let px = 0; px < TILE; px++) {
      const n = (rand() - 0.5) * spread;
      ctx.fillStyle = rgb(base[0] + n, base[1] + n, base[2] + n);
      ctx.fillRect(x + px, y + py, 1, 1);
    }
  }
}

function speckle(ctx, x, y, count, colors, rand) {
  for (let i = 0; i < count; i++) {
    ctx.fillStyle = colors[(rand() * colors.length) | 0];
    ctx.fillRect(x + ((rand() * TILE) | 0), y + ((rand() * TILE) | 0), 1, 1);
  }
}

function drawTile(ctx, tile, painter) {
  const x = (tile % ATLAS_COLS) * TILE;
  const y = ((tile / ATLAS_COLS) | 0) * TILE;
  ctx.save();
  ctx.beginPath();
  ctx.rect(x, y, TILE, TILE);
  ctx.clip();
  painter(x, y, mulberry32(9001 + tile * 7919));
  ctx.restore();
}

export function createAtlas() {
  const canvas = document.createElement('canvas');
  canvas.width = ATLAS_W;
  canvas.height = ATLAS_H;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, ATLAS_W, ATLAS_H);

  drawTile(ctx, T.grassTop, (x, y, rand) => {
    fillNoise(ctx, x, y, [112, 172, 71], 30, rand);
    speckle(ctx, x, y, 16, ['#6b9e43', '#8bc25c', '#7eb34e', '#a1cf6d'], rand);
  });
  drawTile(ctx, T.grassSide, (x, y, rand) => {
    fillNoise(ctx, x, y, [126, 88, 55], 28, rand);
    const edge = [4, 5, 3, 5, 4, 6, 4, 5, 4, 3, 5, 4, 5, 4, 5, 4];
    for (let px = 0; px < TILE; px++) {
      const h = edge[px];
      for (let py = 0; py < h; py++) {
        const n = (rand() - 0.5) * 28;
        ctx.fillStyle = rgb(101 + n, 161 + n, 62 + n);
        ctx.fillRect(x + px, y + py, 1, 1);
      }
      if (rand() > 0.55) {
        ctx.fillStyle = '#639a43';
        ctx.fillRect(x + px, y + h, 1, 1);
      }
    }
    speckle(ctx, x, y + 6, 8, ['#5f4229', '#977044', '#6d4b2c'], rand);
  });
  drawTile(ctx, T.dirt, (x, y, rand) => {
    fillNoise(ctx, x, y, [129, 89, 56], 24, rand);
    speckle(ctx, x, y, 20, ['#76502f', '#a07446', '#8c6138', '#68452a'], rand);
  });
  drawTile(ctx, T.stone, (x, y, rand) => {
    fillNoise(ctx, x, y, [133, 135, 138], 22, rand);
    speckle(ctx, x, y, 12, ['#7c7f83', '#a4a6a8', '#74777a'], rand);
    ctx.fillStyle = 'rgba(90,93,97,0.55)';
    ctx.fillRect(x + 3, y + 7, 4, 1);
    ctx.fillRect(x + 8, y + 11, 5, 1);
    ctx.fillRect(x + 11, y + 4, 1, 3);
  });
  drawTile(ctx, T.cobble, (x, y, rand) => {
    fillNoise(ctx, x, y, [111, 115, 118], 16, rand);
    ctx.strokeStyle = 'rgba(74,77,80,0.9)';
    ctx.lineWidth = 1;
    const stones = [[0,0,7,5],[8,0,8,4],[0,6,4,4],[5,5,5,6],[11,5,5,5],[0,11,6,5],[7,12,9,4],[11,10,5,2]];
    for (const [sx, sy, sw, sh] of stones) {
      ctx.strokeRect(x + sx + 0.5, y + sy + 0.5, sw - 1, sh - 1);
      ctx.fillStyle = 'rgba(160,163,165,0.14)';
      ctx.fillRect(x + sx + 1, y + sy + 1, sw - 2, 1);
    }
  });
  drawTile(ctx, T.sand, (x, y, rand) => {
    fillNoise(ctx, x, y, [224, 208, 154], 16, rand);
    speckle(ctx, x, y, 24, ['#d6c186', '#efe0ad', '#c9b477'], rand);
  });
  drawTile(ctx, T.logSide, (x, y, rand) => {
    fillNoise(ctx, x, y, [114, 79, 43], 16, rand);
    for (let px = 0; px < TILE; px++) {
      if (px % 4 === 0) {
        ctx.fillStyle = 'rgba(66,45,25,0.55)';
        ctx.fillRect(x + px, y, 1, TILE);
      }
      if (px % 4 === 2) {
        ctx.fillStyle = 'rgba(160,112,62,0.35)';
        ctx.fillRect(x + px, y, 1, TILE);
      }
    }
    speckle(ctx, x, y, 10, ['#5d3f23', '#8d602f', '#a5743d'], rand);
  });
  drawTile(ctx, T.logTop, (x, y, rand) => {
    fillNoise(ctx, x, y, [164, 119, 67], 12, rand);
    ctx.strokeStyle = '#7d572e';
    ctx.lineWidth = 1;
    for (let r = 2; r < 8; r += 2) {
      ctx.beginPath();
      ctx.arc(x + 8, y + 8, r, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.fillStyle = '#6d4a27';
    ctx.fillRect(x + 7, y + 7, 2, 2);
  });
  drawTile(ctx, T.leaves, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    fillNoise(ctx, x, y, [55, 112, 45], 34, rand);
    speckle(ctx, x, y, 42, ['#2e6d2c', '#4f963c', '#67ab4b', '#245a23', '#79b95b'], rand);
    for (let i = 0; i < 12; i++) {
      const px = (rand() * TILE) | 0;
      const py = (rand() * TILE) | 0;
      ctx.clearRect(x + px, y + py, 1, 1);
    }
  });
  drawTile(ctx, T.planks, (x, y, rand) => {
    fillNoise(ctx, x, y, [180, 139, 85], 12, rand);
    ctx.fillStyle = 'rgba(104,75,42,0.7)';
    for (let py = 3; py < TILE; py += 4) ctx.fillRect(x, y + py, TILE, 1);
    ctx.fillRect(x + 5, y, 1, 3);
    ctx.fillRect(x + 11, y + 4, 1, 3);
    ctx.fillRect(x + 2, y + 8, 1, 3);
    ctx.fillRect(x + 9, y + 12, 1, 3);
    speckle(ctx, x, y, 8, ['#c79c61', '#9a7447', '#d0a66c'], rand);
  });
  drawTile(ctx, T.glass, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    ctx.fillStyle = 'rgba(190,229,242,0.16)';
    ctx.fillRect(x, y, TILE, TILE);
    ctx.fillStyle = 'rgba(221,248,255,0.85)';
    ctx.fillRect(x, y, TILE, 1);
    ctx.fillRect(x, y + 15, TILE, 1);
    ctx.fillRect(x, y, 1, TILE);
    ctx.fillRect(x + 15, y, 1, TILE);
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.fillRect(x + 3, y + 3, 4, 1);
    ctx.fillRect(x + 3, y + 3, 1, 3);
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.fillRect(x + 10, y + 10, 3, 1);
  });
  drawTile(ctx, T.brick, (x, y, rand) => {
    fillNoise(ctx, x, y, [151, 73, 56], 12, rand);
    ctx.fillStyle = '#d9c5a8';
    for (let row = 0; row < 4; row++) {
      ctx.fillRect(x, y + row * 4, TILE, 1);
      const offset = row % 2 === 0 ? 0 : 4;
      for (let bx = offset; bx < TILE; bx += 8) ctx.fillRect(x + bx, y + row * 4, 1, 4);
    }
    speckle(ctx, x, y, 10, ['#b55946', '#8f4131', '#c06650'], rand);
  });
  drawTile(ctx, T.snow, (x, y, rand) => {
    fillNoise(ctx, x, y, [236, 244, 248], 12, rand);
    speckle(ctx, x, y, 18, ['#d4e3ea', '#ffffff', '#c8dbe4'], rand);
  });
  drawTile(ctx, T.glow, (x, y, rand) => {
    fillNoise(ctx, x, y, [225, 170, 73], 18, rand);
    speckle(ctx, x, y, 30, ['#ffe49a', '#ffc85c', '#c78a35', '#fff4c7'], rand);
    ctx.fillStyle = 'rgba(255,246,203,0.8)';
    for (const [px, py] of [[3,4],[11,3],[6,9],[12,10],[2,12]]) ctx.fillRect(x + px, y + py, 2, 2);
  });
  drawTile(ctx, T.water, (x, y, rand) => {
    fillNoise(ctx, x, y, [55, 124, 201], 18, rand);
    ctx.fillStyle = 'rgba(150,211,246,0.5)';
    ctx.fillRect(x + 2, y + 4, 5, 1);
    ctx.fillRect(x + 9, y + 7, 4, 1);
    ctx.fillRect(x + 4, y + 11, 6, 1);
    ctx.fillRect(x + 12, y + 13, 3, 1);
    ctx.fillStyle = 'rgba(29,88,160,0.5)';
    ctx.fillRect(x + 1, y + 8, 4, 1);
    ctx.fillRect(x + 8, y + 2, 5, 1);
  });
  drawTile(ctx, T.bedrock, (x, y, rand) => {
    fillNoise(ctx, x, y, [70, 73, 79], 34, rand);
    speckle(ctx, x, y, 30, ['#3c3f44', '#54575d', '#2e3034', '#686b70'], rand);
  });
  drawTile(ctx, T.rose, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    ctx.fillStyle = '#3d7a30';
    ctx.fillRect(x + 7, y + 8, 2, 8);
    ctx.fillRect(x + 4, y + 10, 3, 1);
    ctx.fillRect(x + 9, y + 12, 3, 1);
    ctx.fillStyle = '#cf3348';
    ctx.fillRect(x + 5, y + 3, 6, 5);
    ctx.fillStyle = '#f05a67';
    ctx.fillRect(x + 6, y + 3, 2, 2);
    ctx.fillRect(x + 9, y + 5, 1, 1);
    ctx.fillStyle = '#8f1f35';
    ctx.fillRect(x + 7, y + 6, 3, 2);
  });
  drawTile(ctx, T.daisy, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    ctx.fillStyle = '#3d7a30';
    ctx.fillRect(x + 7, y + 8, 2, 8);
    ctx.fillRect(x + 4, y + 12, 3, 1);
    ctx.fillStyle = '#fff8dc';
    ctx.fillRect(x + 5, y + 3, 2, 2);
    ctx.fillRect(x + 9, y + 3, 2, 2);
    ctx.fillRect(x + 7, y + 1, 2, 2);
    ctx.fillRect(x + 7, y + 5, 2, 2);
    ctx.fillRect(x + 5, y + 4, 6, 1);
    ctx.fillStyle = '#f7c948';
    ctx.fillRect(x + 7, y + 3, 2, 2);
  });
  drawTile(ctx, T.tallgrass, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    const blades = [[2,10,2,6],[5,8,1,7],[8,11,1,5],[11,7,2,8],[14,10,1,5],[6,12,1,4],[12,13,1,3]];
    for (const [bx, by, bw, bh] of blades) {
      ctx.fillStyle = rand() > 0.5 ? '#4f963c' : '#63aa48';
      ctx.fillRect(x + bx, y + by, bw, bh);
      ctx.fillRect(x + bx - 1, y + by + 2, bw + 2, 1);
    }
  });
  drawTile(ctx, T.stonebrick, (x, y, rand) => {
    fillNoise(ctx, x, y, [135, 140, 145], 12, rand);
    ctx.fillStyle = 'rgba(84,88,92,0.85)';
    ctx.fillRect(x, y + 7, TILE, 1);
    ctx.fillRect(x, y + 15, TILE, 1);
    ctx.fillRect(x + 7, y, 1, 7);
    ctx.fillRect(x + 3, y + 8, 1, 7);
    ctx.fillRect(x + 12, y + 8, 1, 7);
    ctx.fillStyle = 'rgba(190,194,197,0.35)';
    ctx.fillRect(x, y, TILE, 1);
    ctx.fillRect(x, y + 8, TILE, 1);
  });
  drawTile(ctx, T.clouds, (x, y, rand) => {
    ctx.clearRect(x, y, TILE, TILE);
    ctx.fillStyle = 'rgba(255,255,255,0.88)';
    ctx.fillRect(x, y, TILE, TILE);
  });

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  texture.generateMipmaps = false;
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  return texture;
}

export const TILE_UV = [];
for (let tile = 0; tile < ATLAS_COLS * ATLAS_ROWS; tile++) {
  const col = tile % ATLAS_COLS;
  const row = (tile / ATLAS_COLS) | 0;
  const pad = 0.12;
  TILE_UV[tile] = {
    u0: (col * TILE + pad) / ATLAS_W,
    u1: ((col + 1) * TILE - pad) / ATLAS_W,
    v0: 1 - ((row + 1) * TILE - pad) / ATLAS_H,
    v1: 1 - (row * TILE + pad) / ATLAS_H,
  };
}

// Small isometric cube icons for the HUD, rendered from the same pixel tiles.
export function makeBlockIcon(blockId, size = 64) {
  const b = BLOCKS[blockId];
  if (!b) return '';
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const atlas = createAtlas().image;
  const tileCanvas = (tile) => {
    const c = document.createElement('canvas');
    c.width = TILE; c.height = TILE;
    c.getContext('2d').drawImage(atlas, (tile % ATLAS_COLS) * TILE, ((tile / ATLAS_COLS) | 0) * TILE, TILE, TILE, 0, 0, TILE, TILE);
    return c;
  };
  const top = tileCanvas(b.tiles.top);
  const side = tileCanvas(b.tiles.side);
  const s = size / 32;
  const face = (img, origin, ux, uy, vx, vy, shade) => {
    ctx.save();
    ctx.setTransform(ux, uy, vx, vy, origin[0], origin[1]);
    ctx.drawImage(img, 0, 0, TILE, TILE, 0, 0, 1, 1);
    if (shade > 0) {
      ctx.globalCompositeOperation = 'source-atop';
      ctx.fillStyle = `rgba(0,0,0,${shade})`;
      ctx.fillRect(0, 0, 1, 1);
    }
    ctx.restore();
  };
  face(top, [2 * s, 9 * s], 14 * s, -7 * s, 14 * s, 7 * s, 0);
  face(side, [2 * s, 9 * s], 14 * s, 7 * s, 0, 14 * s, 0.16);
  face(side, [16 * s, 16 * s], 14 * s, -7 * s, 0, 14 * s, 0.32);
  ctx.strokeStyle = 'rgba(20,30,35,0.35)';
  ctx.lineWidth = Math.max(1, s);
  ctx.beginPath();
  ctx.moveTo(16 * s, 2 * s);
  ctx.lineTo(30 * s, 9 * s);
  ctx.lineTo(16 * s, 16 * s);
  ctx.lineTo(2 * s, 9 * s);
  ctx.closePath();
  ctx.stroke();
  return canvas.toDataURL();
}

// Procedural voxel island: terrain generation, chunk meshing and world editing.
import * as THREE from 'three';
import {
  BLOCK, BLOCKS, TILE_UV, createAtlas, isOpaque, isCross, isLiquid,
} from './blocks.js';

export const SX = 128;
export const SZ = 128;
export const SY = 48;
export const SEA = 13;
export const CHUNK = 16;
export const CHUNKS_X = SX / CHUNK;
export const CHUNKS_Z = SZ / CHUNK;

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
const fract = (n) => n - Math.floor(n);

function hash2(x, z, seed) {
  return fract(Math.sin(x * 127.1 + z * 311.7 + seed * 0.0137) * 43758.5453123);
}

function valueNoise(x, z, seed) {
  const xi = Math.floor(x);
  const zi = Math.floor(z);
  const xf = x - xi;
  const zf = z - zi;
  const u = xf * xf * (3 - 2 * xf);
  const v = zf * zf * (3 - 2 * zf);
  const a = hash2(xi, zi, seed);
  const b = hash2(xi + 1, zi, seed);
  const c = hash2(xi, zi + 1, seed);
  const d = hash2(xi + 1, zi + 1, seed);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}

function fbm(x, z, seed, octaves = 4) {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  let fx = x;
  let fz = z;
  for (let i = 0; i < octaves; i++) {
    sum += valueNoise(fx, fz, seed + i * 131) * amp;
    norm += amp;
    amp *= 0.5;
    fx *= 2.03;
    fz *= 2.01;
  }
  return sum / norm;
}

// Face geometry definitions. (u x v) points out of the block.
const FACES = [
  { n: [1, 0, 0], base: [1, 0, 1], u: [0, 0, -1], v: [0, 1, 0], shade: 0.79, tile: 'side' },
  { n: [-1, 0, 0], base: [0, 0, 0], u: [0, 0, 1], v: [0, 1, 0], shade: 0.72, tile: 'side' },
  { n: [0, 1, 0], base: [0, 1, 1], u: [1, 0, 0], v: [0, 0, -1], shade: 1.0, tile: 'top' },
  { n: [0, -1, 0], base: [0, 0, 0], u: [1, 0, 0], v: [0, 0, 1], shade: 0.52, tile: 'bottom' },
  { n: [0, 0, 1], base: [0, 0, 1], u: [1, 0, 0], v: [0, 1, 0], shade: 0.88, tile: 'side' },
  { n: [0, 0, -1], base: [1, 0, 0], u: [-1, 0, 0], v: [0, 1, 0], shade: 0.82, tile: 'side' },
];
const FACE_UVS = [[0, 0], [1, 0], [1, 1], [0, 1]];
const AO_LEVELS = [0.48, 0.66, 0.83, 1.0];

class GeoBuilder {
  constructor() {
    this.pos = [];
    this.nrm = [];
    this.uv = [];
    this.col = [];
    this.idx = [];
  }

  quad(points, normal, uv, colors) {
    const base = this.pos.length / 3;
    for (let i = 0; i < 4; i++) {
      this.pos.push(points[i][0], points[i][1], points[i][2]);
      this.nrm.push(normal[0], normal[1], normal[2]);
      this.uv.push(uv[i][0], uv[i][1]);
      this.col.push(colors[i], colors[i], colors[i]);
    }
    this.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
  }

  build() {
    if (!this.idx.length) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    g.setIndex(this.idx);
    g.computeBoundingSphere();
    return g;
  }
}

export class VoxelWorld {
  constructor(seed = 123456) {
    this.seed = seed | 0;
    this.data = new Uint8Array(SX * SY * SZ);
    this.heights = new Uint8Array(SX * SZ);
    this.edits = new Map();
    this.chunks = new Map();
    this.dirty = new Set();
    this.group = new THREE.Group();
    this.group.name = 'island';
    this.atlas = createAtlas();
    this.materials = {
      opaque: new THREE.MeshBasicMaterial({ map: this.atlas, vertexColors: true }),
      cutout: new THREE.MeshBasicMaterial({ map: this.atlas, vertexColors: true, alphaTest: 0.45 }),
      flower: new THREE.MeshBasicMaterial({ map: this.atlas, vertexColors: true, alphaTest: 0.4, side: THREE.DoubleSide }),
      glass: new THREE.MeshBasicMaterial({ map: this.atlas, vertexColors: true, transparent: true, opacity: 0.72, depthWrite: false }),
      water: new THREE.MeshBasicMaterial({ map: this.atlas, vertexColors: true, transparent: true, opacity: 0.72, depthWrite: false, side: THREE.DoubleSide }),
    };
    this.materials.glass.color.setHex(0xffffff);
    this.materials.water.color.setHex(0xd8ecff);
    this.tint = new THREE.Color(1, 1, 1);
    this.generate();
  }

  index(x, y, z) {
    return x + SX * (z + SZ * y);
  }

  inBounds(x, y, z) {
    return x >= 0 && x < SX && y >= 0 && y < SY && z >= 0 && z < SZ;
  }

  getBlock(x, y, z) {
    if (!this.inBounds(x, y, z)) return BLOCK.AIR;
    return this.data[this.index(x, y, z)];
  }

  setBlock(x, y, z, id, record = true) {
    if (!this.inBounds(x, y, z)) return false;
    const i = this.index(x, y, z);
    if (this.data[i] === id) return false;
    this.data[i] = id;
    if (record) this.edits.set(i, id);
    const cx = Math.floor(x / CHUNK);
    const cz = Math.floor(z / CHUNK);
    this.markChunkDirty(cx, cz);
    if (x % CHUNK === 0) this.markChunkDirty(cx - 1, cz);
    if (x % CHUNK === CHUNK - 1) this.markChunkDirty(cx + 1, cz);
    if (z % CHUNK === 0) this.markChunkDirty(cx, cz - 1);
    if (z % CHUNK === CHUNK - 1) this.markChunkDirty(cx, cz + 1);
    return true;
  }

  markChunkDirty(cx, cz) {
    if (cx < 0 || cx >= CHUNKS_X || cz < 0 || cz >= CHUNKS_Z) return;
    this.dirty.add(`${cx},${cz}`);
  }

  columnHeight(x, z) {
    if (x < 0 || x >= SX || z < 0 || z >= SZ) return 0;
    return this.heights[x + z * SX];
  }

  findSpawn() {
    const cx = SX / 2;
    const cz = SZ / 2;
    let best = null;
    for (let r = 0; r <= 26; r++) {
      for (let dx = -r; dx <= r; dx++) {
        for (const dz of [-r, r]) {
          const x = Math.floor(cx + dx);
          const z = Math.floor(cz + dz);
          const h = this.columnHeight(x, z);
          const top = this.getBlock(x, h, z);
          if ((top === BLOCK.GRASS || top === BLOCK.SAND) && h > SEA + 1) {
            best = { x: x + 0.5, z: z + 0.5, y: h + 1.01, h };
            if (r < 2) return best;
          }
        }
      }
      if (best) return best;
      for (let dz = -r + 1; dz < r; dz++) {
        for (const dx of [-r, r]) {
          const x = Math.floor(cx + dx);
          const z = Math.floor(cz + dz);
          const h = this.columnHeight(x, z);
          const top = this.getBlock(x, h, z);
          if ((top === BLOCK.GRASS || top === BLOCK.SAND) && h > SEA + 1) {
            best = { x: x + 0.5, z: z + 0.5, y: h + 1.01, h };
          }
        }
      }
      if (best) return best;
    }
    return best || { x: cx + 0.5, z: cz + 0.5, y: SEA + 5, h: SEA + 4 };
  }

  generate() {
    const seed = this.seed;
    const heights = new Int16Array(SX * SZ);
    const moisture = new Float32Array(SX * SZ);
    const temp = new Float32Array(SX * SZ);
    const radius = SX / 2 - 3;

    for (let z = 0; z < SZ; z++) {
      for (let x = 0; x < SX; x++) {
        const nx = (x - SX / 2) / radius;
        const nz = (z - SZ / 2) / radius;
        const dist = Math.sqrt(nx * nx + nz * nz) * radius;
        const island = 1 - smoothstep(37, 61, dist);
        const base = 15.5
          + fbm(x * 0.024, z * 0.024, seed, 4) * 12.5
          + fbm(x * 0.065, z * 0.065, seed + 17, 3) * 4.2
          + fbm(x * 0.011 + 31, z * 0.011 + 9, seed + 51, 2) * 7.0;
        const ridge = Math.max(0, fbm(x * 0.014 + 77, z * 0.014 + 21, seed + 99, 3) - 0.53);
        const mountain = ridge * 36 * smoothstep(0.3, 0.7, fbm(x * 0.009, z * 0.009, seed + 200, 2));
        let h = base + mountain;
        h = (SEA - 7) + (h - (SEA - 7)) * island;
        // Small sandy coves around the shoreline.
        if (h > SEA - 1 && h < SEA + 2.5 && hash2(x, z, seed + 7) > 0.55) h = SEA + 1;
        heights[x + z * SX] = Math.round(clamp(h, 2, SY - 9));
        moisture[x + z * SX] = fbm(x * 0.021 + 40, z * 0.021 + 80, seed + 303, 3);
        temp[x + z * SX] = fbm(x * 0.018 + 100, z * 0.018 + 55, seed + 404, 3);
      }
    }

    for (let z = 0; z < SZ; z++) {
      for (let x = 0; x < SX; x++) {
        const h = heights[x + z * SX];
        this.heights[x + z * SX] = h;
        const slope = Math.max(
          Math.abs(h - heights[Math.max(0, x - 1) + z * SX]),
          Math.abs(h - heights[Math.min(SX - 1, x + 1) + z * SX]),
          Math.abs(h - heights[x + Math.max(0, z - 1) * SX]),
          Math.abs(h - heights[x + Math.min(SZ - 1, z + 1) * SX]),
        );
        const moist = moisture[x + z * SX];
        const tempv = temp[x + z * SX];
        let top = BLOCK.GRASS;
        if (h <= SEA + 1) top = BLOCK.SAND;
        else if (h >= 31 || (tempv < 0.30 && h > SEA + 3)) top = BLOCK.SNOW;
        else if (moist < 0.34 && h < 24) top = BLOCK.SAND;
        else if (slope >= 4 && h > 24) top = BLOCK.STONE;

        for (let y = 0; y <= h; y++) {
          let id;
          if (y === 0) id = BLOCK.BEDROCK;
          else if (y === h) id = top;
          else if (y >= h - 3) id = (top === BLOCK.SAND) ? BLOCK.SAND : (top === BLOCK.SNOW ? BLOCK.SNOW : (top === BLOCK.STONE ? BLOCK.STONE : BLOCK.DIRT));
          else id = BLOCK.STONE;
          this.data[this.index(x, y, z)] = id;
        }
        for (let y = h + 1; y <= SEA; y++) {
          this.data[this.index(x, y, z)] = BLOCK.WATER;
        }
        // A few glowing stone pockets deep underground to make mining rewarding.
        if (h > 22 && hash2(x * 3.1, z * 2.7, seed + 91) > 0.994) {
          const oy = 3 + ((hash2(x, z, seed + 5) * (h - 6)) | 0);
          this.data[this.index(x, oy, z)] = BLOCK.GLOWSTONE;
        }
      }
    }

    // Trees -----------------------------------------------------------------
    let rngState = (seed ^ 0x9e3779b9) >>> 0;
    const rand = () => {
      rngState |= 0;
      rngState = (rngState + 0x6D2B79F5) | 0;
      let t = Math.imul(rngState ^ (rngState >>> 15), 1 | rngState);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };

    for (let z = 3; z < SZ - 3; z++) {
      for (let x = 3; x < SX - 3; x++) {
        const h = heights[x + z * SX];
        if (h <= SEA + 1 || h > 29) continue;
        const top = this.data[this.index(x, h, z)];
        if (top !== BLOCK.GRASS) continue;
        const moist = moisture[x + z * SX];
        const chance = moist > 0.52 ? 0.033 : 0.006;
        if (rand() > chance) continue;
        const dx = x - SX / 2;
        const dz = z - SZ / 2;
        if (dx * dx + dz * dz < 30) continue;
        if (this.getBlock(x, h + 1, z) !== BLOCK.AIR) continue;
        let trunk = 4 + ((rand() * 3) | 0);
        let clear = true;
        for (let y = 1; y <= trunk + 2; y++) {
          if (this.getBlock(x, h + y, z) !== BLOCK.AIR) { clear = false; break; }
        }
        if (!clear) continue;
        for (let y = 1; y <= trunk; y++) this.data[this.index(x, h + y, z)] = BLOCK.LOG;
        for (let ly = trunk - 2; ly <= trunk + 1; ly++) {
          const r = ly >= trunk ? 1 : 2;
          for (let lz = -r; lz <= r; lz++) {
            for (let lx = -r; lx <= r; lx++) {
              if (lx === 0 && lz === 0 && ly <= trunk) continue;
              if (Math.abs(lx) === r && Math.abs(lz) === r && rand() > 0.45) continue;
              if (ly === trunk + 1 && Math.abs(lx) + Math.abs(lz) > 1) continue;
              const bx = x + lx;
              const by = h + ly;
              const bz = z + lz;
              if (this.inBounds(bx, by, bz) && this.getBlock(bx, by, bz) === BLOCK.AIR) {
                this.data[this.index(bx, by, bz)] = BLOCK.LEAVES;
              }
            }
          }
        }
        this.data[this.index(x, h + trunk + 1, z)] = BLOCK.LEAVES;
      }
    }

    // Flowers and grass tufts ------------------------------------------------
    for (let z = 2; z < SZ - 2; z++) {
      for (let x = 2; x < SX - 2; x++) {
        const h = heights[x + z * SX];
        if (h <= SEA + 1 || h > 30) continue;
        if (this.getBlock(x, h, z) !== BLOCK.GRASS) continue;
        if (this.getBlock(x, h + 1, z) !== BLOCK.AIR) continue;
        const r = hash2(x * 5.3, z * 7.9, seed + 606);
        if (r > 0.968) {
          const pick = hash2(x, z, seed + 707);
          this.data[this.index(x, h + 1, z)] = pick < 0.34 ? BLOCK.ROSE : pick < 0.68 ? BLOCK.DAISY : BLOCK.TALLGRASS;
        }
      }
    }

    // Apply saved edits after generation.
    for (const [i, id] of this.edits) this.data[i] = id;
  }

  applyEdits(edits) {
    for (const [i, id] of edits) {
      if (i >= 0 && i < this.data.length) {
        this.data[i] = id;
        this.edits.set(i, id);
      }
    }
  }

  faceVisible(cur, nb) {
    if (nb === BLOCK.AIR || isCross(nb)) return true;
    if (cur === BLOCK.WATER) return nb !== BLOCK.WATER && !isOpaque(nb);
    if (cur === BLOCK.GLASS) return nb !== BLOCK.GLASS && !isOpaque(nb);
    if (cur === BLOCK.LEAVES) return nb !== BLOCK.LEAVES && !isOpaque(nb);
    if (isOpaque(cur)) return !isOpaque(nb);
    return true;
  }

  chunkKey(cx, cz) { return `${cx},${cz}`; }

  buildChunk(cx, cz) {
    if (cx < 0 || cx >= CHUNKS_X || cz < 0 || cz >= CHUNKS_Z) return;
    const key = this.chunkKey(cx, cz);
    let record = this.chunks.get(key);
    if (record) {
      for (const mesh of record.meshes) {
        this.group.remove(mesh);
        mesh.geometry.dispose();
      }
    }
    const builders = {
      opaque: new GeoBuilder(),
      cutout: new GeoBuilder(),
      flower: new GeoBuilder(),
      glass: new GeoBuilder(),
      water: new GeoBuilder(),
    };
    const x0 = cx * CHUNK;
    const z0 = cz * CHUNK;

    for (let y = 0; y < SY; y++) {
      for (let z = z0; z < z0 + CHUNK; z++) {
        for (let x = x0; x < x0 + CHUNK; x++) {
          const id = this.data[this.index(x, y, z)];
          if (id === BLOCK.AIR || id === BLOCK.WATER) {
            if (id === BLOCK.WATER) this.addWater(builders.water, x, y, z);
            continue;
          }
          const block = BLOCKS[id];
          if (isCross(id)) {
            this.addCross(builders.flower, x, y, z, block.tiles.top);
            continue;
          }
          const builder = id === BLOCK.GLASS ? builders.glass : (id === BLOCK.LEAVES ? builders.cutout : builders.opaque);
          for (const face of FACES) {
            const nx = x + face.n[0];
            const ny = y + face.n[1];
            const nz = z + face.n[2];
            if (!this.faceVisible(id, this.getBlock(nx, ny, nz))) continue;
            this.addFace(builder, x, y, z, id, face, block);
          }
        }
      }
    }

    const meshes = [];
    const groupNames = ['opaque', 'cutout', 'flower', 'glass', 'water'];
    for (const name of groupNames) {
      const geometry = builders[name].build();
      if (!geometry) continue;
      const mesh = new THREE.Mesh(geometry, this.materials[name]);
      mesh.frustumCulled = true;
      mesh.renderOrder = name === 'water' ? 2 : name === 'glass' ? 1 : 0;
      mesh.castShadow = false;
      mesh.receiveShadow = false;
      this.group.add(mesh);
      meshes.push(mesh);
    }
    const sphere = new THREE.Sphere();
    let centerY = 0;
    for (const mesh of meshes) {
      if (mesh.geometry.boundingSphere) centerY += mesh.geometry.boundingSphere.center.y;
    }
    sphere.radius = 22;
    this.chunks.set(key, { meshes, cx, cz, built: true });
    this.dirty.delete(key);
  }

  addFace(builder, x, y, z, id, face, block) {
    const tile = block.tiles[face.tile];
    const uv = TILE_UV[tile];
    const pts = [];
    const colors = [];
    const du = face.u;
    const dv = face.v;
    for (let i = 0; i < 4; i++) {
      const cu = i === 1 || i === 2 ? 1 : 0;
      const cv = i >= 2 ? 1 : 0;
      pts.push([
        x + face.base[0] + du[0] * cu + dv[0] * cv,
        y + face.base[1] + du[1] * cu + dv[1] * cv,
        z + face.base[2] + du[2] * cu + dv[2] * cv,
      ]);
      // Ambient occlusion: sample the three blocks around this corner on the
      // outside of the face. Cross-shaped decoration never reaches here.
      const sx = cu ? 1 : -1;
      const sz = cv ? 1 : -1;
      const ox = x + face.n[0];
      const oy = y + face.n[1];
      const oz = z + face.n[2];
      const side1 = isOpaque(this.getBlock(ox + du[0] * sx, oy + du[1] * sx, oz + du[2] * sx)) ? 1 : 0;
      const side2 = isOpaque(this.getBlock(ox + dv[0] * sz, oy + dv[1] * sz, oz + dv[2] * sz)) ? 1 : 0;
      const corner = isOpaque(this.getBlock(ox + du[0] * sx + dv[0] * sz, oy + du[1] * sx + dv[1] * sz, oz + du[2] * sx + dv[2] * sz)) ? 1 : 0;
      const ao = side1 && side2 ? 0 : 3 - (side1 + side2 + corner);
      const shade = face.shade * (id === BLOCK.WATER ? 0.94 : AO_LEVELS[ao]);
      colors.push(shade);
    }
    const uvs = [
      [uv.u0, uv.v0], [uv.u1, uv.v0], [uv.u1, uv.v1], [uv.u0, uv.v1],
    ];
    builder.quad(pts, face.n, uvs, colors);
  }

  addWater(builder, x, y, z) {
    // Water gets only the surfaces that can actually be seen: the top layer and
    // the sides touching air at the shoreline. Avoids thousands of hidden quads.
    if (this.getBlock(x, y + 1, z) !== BLOCK.WATER) {
      this.addSimpleFace(builder, x, y, z, 'top', 1, 0.9);
    }
    const neighbours = [
      [1, 0, 0, 'side'], [-1, 0, 0, 'side'], [0, 0, 1, 'side'], [0, 0, -1, 'side'],
    ];
    for (const [dx, dy, dz] of neighbours) {
      const nb = this.getBlock(x + dx, y + dy, z + dz);
      if (nb === BLOCK.AIR || isCross(nb)) {
        // Build an inward/outward facing side using the appropriate face.
        const face = FACES.find((f) => f.n[0] === dx && f.n[2] === dz);
        if (!face) continue;
        const uv = TILE_UV[BLOCKS[BLOCK.WATER].tiles.side];
        const pts = [];
        for (let i = 0; i < 4; i++) {
          const cu = i === 1 || i === 2 ? 1 : 0;
          const cv = i >= 2 ? 1 : 0;
          pts.push([
            x + face.base[0] + face.u[0] * cu + face.v[0] * cv,
            y + face.base[1] + face.u[1] * cu + face.v[1] * cv,
            z + face.base[2] + face.u[2] * cu + face.v[2] * cv,
          ]);
        }
        const uvs = [[uv.u0, uv.v0], [uv.u1, uv.v0], [uv.u1, uv.v1], [uv.u0, uv.v1]];
        builder.quad(pts, face.n, uvs, [0.85, 0.85, 0.85, 0.85]);
      }
    }
  }

  addSimpleFace(builder, x, y, z, tileKey, tileRow, shade) {
    // Used for water's top: exactly the +Y face.
    const tile = BLOCKS[BLOCK.WATER].tiles[tileKey];
    const uv = TILE_UV[tile];
    const pts = [
      [x, y + 0.92, z + 1],
      [x + 1, y + 0.92, z + 1],
      [x + 1, y + 0.92, z],
      [x, y + 0.92, z],
    ];
    const uvs = [[uv.u0, uv.v1], [uv.u1, uv.v1], [uv.u1, uv.v0], [uv.u0, uv.v0]];
    builder.quad(pts, [0, 1, 0], uvs, [shade, shade, shade, shade]);
  }

  addCross(builder, x, y, z, tile) {
    const uv = TILE_UV[tile];
    const inset = 0.12;
    const uvs = [[uv.u0, uv.v0], [uv.u1, uv.v0], [uv.u1, uv.v1], [uv.u0, uv.v1]];
    const a = [
      [x + inset, y, z + inset],
      [x + 1 - inset, y, z + 1 - inset],
      [x + 1 - inset, y + 1, z + 1 - inset],
      [x + inset, y + 1, z + inset],
    ];
    const b = [
      [x + inset, y, z + 1 - inset],
      [x + 1 - inset, y, z + inset],
      [x + 1 - inset, y + 1, z + inset],
      [x + inset, y + 1, z + 1 - inset],
    ];
    builder.quad(a, [0, 0, 1], uvs, [1, 1, 1, 1]);
    builder.quad(b, [0, 0, 1], uvs, [1, 1, 1, 1]);
  }

  flushDirty(limit = 6) {
    if (!this.dirty.size) return 0;
    let count = 0;
    for (const key of this.dirty) {
      const [cx, cz] = key.split(',').map(Number);
      this.buildChunk(cx, cz);
      count++;
      if (count >= limit) break;
    }
    return count;
  }

  setTint(light, night = false) {
    this.tint.setRGB(light * (night ? 0.84 : 1), light * (night ? 0.92 : 1), light * (night ? 1.08 : 1));
    for (const mat of Object.values(this.materials)) mat.color.copy(this.tint);
    this.materials.water.color.multiply(new THREE.Color(0.82, 0.92, 1.0));
  }

  solidAt(x, y, z) {
    return isOpaque(this.getBlock(x, y, z));
  }

  topSolidY(x, z) {
    for (let y = SY - 1; y >= 0; y--) {
      const id = this.getBlock(x, y, z);
      if (id !== BLOCK.AIR && id !== BLOCK.WATER && !isCross(id)) return y + 1;
    }
    return 0;
  }
}

// Sky dome, sun/moon, stars, clouds and night fireflies.
import * as THREE from 'three';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function smoothstep(a, b, x) {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function glowTexture(inner, outer) {
  const c = document.createElement('canvas');
  c.width = 128;
  c.height = 128;
  const ctx = c.getContext('2d');
  const grad = ctx.createRadialGradient(64, 64, 4, 64, 64, 64);
  grad.addColorStop(0, inner);
  grad.addColorStop(0.35, outer);
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 128, 128);
  const texture = new THREE.CanvasTexture(c);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

export class SkySystem {
  constructor(scene, seed = 1) {
    this.scene = scene;
    this.dayTop = new THREE.Color('#63b4f4');
    this.dayHorizon = new THREE.Color('#d4ecfb');
    this.nightTop = new THREE.Color('#060d20');
    this.nightHorizon = new THREE.Color('#14213d');
    this.sunsetTop = new THREE.Color('#4d74b0');
    this.sunsetHorizon = new THREE.Color('#ffa45f');
    this.horizonColor = new THREE.Color('#d4ecfb');
    this.topColor = new THREE.Color('#63b4f4');
    this.daylight = 1;
    this.sunDir = new THREE.Vector3(0, 1, 0);
    this.time = 0.33;

    const skyGeo = new THREE.SphereGeometry(280, 32, 18);
    this.skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        topColor: { value: this.topColor },
        horizonColor: { value: this.horizonColor },
        sunDirection: { value: this.sunDir },
        sunColor: { value: new THREE.Color('#fff3c4') },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 topColor;
        uniform vec3 horizonColor;
        uniform vec3 sunDirection;
        uniform vec3 sunColor;
        void main() {
          float h = clamp(vDir.y, -1.0, 1.0);
          float t = smoothstep(-0.06, 0.62, h);
          vec3 col = mix(horizonColor, topColor, t);
          float horizonBand = 1.0 - smoothstep(0.0, 0.28, abs(h));
          col = mix(col, horizonColor, horizonBand * 0.18);
          float sunAmount = max(dot(normalize(vDir), normalize(sunDirection)), 0.0);
          col += sunColor * pow(sunAmount, 34.0) * 0.18;
          col += sunColor * pow(sunAmount, 6.0) * 0.045;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(skyGeo, this.skyMat);
    this.sky.frustumCulled = false;
    this.sky.renderOrder = -10;
    scene.add(this.sky);

    // Sun and moon ---------------------------------------------------------
    const sunTex = glowTexture('rgba(255,252,230,1)', 'rgba(255,220,126,0.9)');
    this.sun = new THREE.Sprite(new THREE.SpriteMaterial({
      map: sunTex, color: 0xffffff, transparent: true, depthWrite: false, fog: false, blending: THREE.AdditiveBlending,
    }));
    this.sun.scale.set(30, 30, 1);
    this.sun.renderOrder = -8;
    scene.add(this.sun);

    const moonTex = glowTexture('rgba(240,246,255,1)', 'rgba(180,201,238,0.8)');
    this.moon = new THREE.Sprite(new THREE.SpriteMaterial({
      map: moonTex, color: 0xdfe8ff, transparent: true, depthWrite: false, fog: false,
    }));
    this.moon.scale.set(20, 20, 1);
    this.moon.renderOrder = -8;
    scene.add(this.moon);

    // Stars ----------------------------------------------------------------
    const starPositions = [];
    const rand = mulberry32(seed + 88);
    for (let i = 0; i < 420; i++) {
      const theta = rand() * Math.PI * 2;
      const y = Math.pow(rand(), 0.55);
      const r = Math.sqrt(1 - y * y);
      starPositions.push(Math.cos(theta) * r * 260, y * 250, Math.sin(theta) * r * 260);
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPositions, 3));
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
      color: 0xffffff, size: 1.35, sizeAttenuation: true, transparent: true, opacity: 0,
      depthWrite: false, fog: false,
    }));
    this.stars.renderOrder = -9;
    scene.add(this.stars);

    // Clouds ---------------------------------------------------------------
    const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
    const cloudMat = new THREE.MeshBasicMaterial({
      color: 0xffffff, transparent: true, opacity: 0.78, depthWrite: false, fog: true,
    });
    const count = 110;
    this.clouds = new THREE.InstancedMesh(cloudGeo, cloudMat, count);
    this.clouds.frustumCulled = false;
    this.clouds.renderOrder = 3;
    this.cloudData = [];
    const cr = mulberry32(seed + 192);
    const dummy = new THREE.Object3D();
    for (let i = 0; i < count; i++) {
      const cluster = Math.floor(i / 4);
      const cx = (cr() - 0.5) * 250;
      const cz = (cr() - 0.5) * 250;
      const cy = 49 + cr() * 10;
      const sx = 5 + cr() * 9;
      const sy = 1.4 + cr() * 1.6;
      const sz = 4 + cr() * 6;
      this.cloudData.push({ x: cx, y: cy, z: cz, sx, sy, sz, speed: 0.45 + cr() * 0.35, phase: cluster });
      dummy.position.set(cx, cy, cz);
      dummy.scale.set(sx, sy, sz);
      dummy.updateMatrix();
      this.clouds.setMatrixAt(i, dummy.matrix);
    }
    this.clouds.instanceMatrix.needsUpdate = true;
    scene.add(this.clouds);

    // Fireflies ------------------------------------------------------------
    const firePositions = [];
    const fr = mulberry32(seed + 404);
    this.fireflyBase = [];
    for (let i = 0; i < 55; i++) {
      const x = (fr() - 0.5) * 90;
      const z = (fr() - 0.5) * 90;
      const y = 5 + fr() * 12;
      this.fireflyBase.push({ x, y, z, phase: fr() * 10, speed: 0.3 + fr() * 0.6 });
      firePositions.push(x, y, z);
    }
    const fireGeo = new THREE.BufferGeometry();
    fireGeo.setAttribute('position', new THREE.Float32BufferAttribute(firePositions, 3));
    this.fireflies = new THREE.Points(fireGeo, new THREE.PointsMaterial({
      color: 0xffe98a, size: 0.28, sizeAttenuation: true, transparent: true, opacity: 0,
      depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    scene.add(this.fireflies);

    this.clouds.material.color.setRGB(1, 1, 1);
    this.tmpColor = new THREE.Color();
    this.cloudDummy = new THREE.Object3D();
  }

  update(time, camera, dt) {
    this.time = time;
    const angle = (time - 0.25) * Math.PI * 2;
    this.sunDir.set(Math.cos(angle), Math.sin(angle), 0.3).normalize();
    const sunY = this.sunDir.y;
    this.daylight = smoothstep(-0.1, 0.2, sunY);
    const twilight = (1 - smoothstep(0.0, 0.34, Math.abs(sunY))) * smoothstep(-0.2, 0.0, sunY) * 0.9;

    this.topColor.copy(this.nightTop).lerp(this.dayTop, this.daylight);
    this.horizonColor.copy(this.nightHorizon).lerp(this.dayHorizon, this.daylight);
    if (twilight > 0.001) {
      this.topColor.lerp(this.sunsetTop, twilight * 0.4);
      this.horizonColor.lerp(this.sunsetHorizon, twilight * 0.95);
    }

    this.sky.position.copy(camera.position);
    this.stars.position.copy(camera.position);
    this.stars.rotation.y += dt * 0.004;
    this.stars.material.opacity = (1 - this.daylight) * 0.95;
    this.sun.position.copy(camera.position).addScaledVector(this.sunDir, 235);
    this.moon.position.copy(camera.position).addScaledVector(this.sunDir, -235);
    this.sun.material.opacity = smoothstep(-0.16, 0.12, sunY);
    this.moon.material.opacity = smoothstep(-0.12, 0.16, -sunY) * 0.95;

    // Clouds drift with a soft wrap.
    for (let i = 0; i < this.cloudData.length; i++) {
      const c = this.cloudData[i];
      c.x += c.speed * dt;
      if (c.x > 140) c.x -= 280;
      this.cloudDummy.position.set(c.x, c.y, c.z);
      this.cloudDummy.scale.set(c.sx, c.sy, c.sz);
      this.cloudDummy.updateMatrix();
      this.clouds.setMatrixAt(i, this.cloudDummy.matrix);
    }
    this.clouds.instanceMatrix.needsUpdate = true;
    const cloudLight = 0.4 + 0.6 * this.daylight;
    this.clouds.material.color.setRGB(cloudLight, cloudLight * 1.01, cloudLight * 1.07);
    this.clouds.material.opacity = 0.68 + 0.12 * this.daylight;

    // Fireflies bob around at night.
    const pos = this.fireflies.geometry.attributes.position;
    const t = performance.now() * 0.001;
    for (let i = 0; i < this.fireflyBase.length; i++) {
      const f = this.fireflyBase[i];
      pos.setXYZ(
        i,
        f.x + Math.sin(t * f.speed + f.phase) * 1.4,
        f.y + Math.sin(t * f.speed * 1.4 + f.phase * 2) * 0.7,
        f.z + Math.cos(t * f.speed + f.phase) * 1.4,
      );
    }
    pos.needsUpdate = true;
    this.fireflies.material.opacity = (1 - this.daylight) * 0.85;

    return {
      daylight: this.daylight,
      light: 0.34 + 0.66 * this.daylight,
      horizon: this.horizonColor,
    };
  }
}

// Little blocky pigs that wander around the island.
import * as THREE from 'three';
import { BLOCK } from './blocks.js';

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const PINK = 0xeaa5a1;
const PINK_DARK = 0xd88784;
const SNOUT = 0xc87372;
const HOOF = 0x9c5d5a;

function box(w, h, d, color, x, y, z, mats) {
  const material = mats[color] || (mats[color] = new THREE.MeshLambertMaterial({ color }));
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  return mesh;
}

export class PigManager {
  constructor(scene, world, spawn) {
    this.scene = scene;
    this.world = world;
    this.pigs = [];
    this.materials = {};
    this.baseColors = new Map();
    const rand = mulberry32(world.seed + 777);
    const positions = [];
    for (let tries = 0; tries < 400 && positions.length < 5; tries++) {
      const angle = rand() * Math.PI * 2;
      const dist = 8 + rand() * 25;
      const x = spawn.x + Math.cos(angle) * dist;
      const z = spawn.z + Math.sin(angle) * dist;
      if (x < 12 || x > 116 || z < 12 || z > 116) continue;
      const y = world.topSolidY(Math.floor(x), Math.floor(z));
      const top = world.getBlock(Math.floor(x), y - 1, Math.floor(z));
      if (top === BLOCK.GRASS && y > 13) positions.push({ x, z, y });
    }
    for (let i = 0; i < Math.max(3, positions.length); i++) {
      const p = positions[i % Math.max(1, positions.length)] || { x: spawn.x + 6, z: spawn.z, y: spawn.y };
      this.createPig(p.x + (rand() - 0.5) * 2, p.z + (rand() - 0.5) * 2, p.y, rand);
    }
  }

  createPig(x, z, y, rand) {
    const root = new THREE.Group();
    const mats = this.materials;
    const body = box(0.82, 0.58, 1.2, PINK, 0, 0.62, 0, mats);
    root.add(body);
    const head = box(0.58, 0.52, 0.48, PINK, 0, 0.78, 0.78, mats);
    root.add(head);
    root.add(box(0.3, 0.2, 0.16, SNOUT, 0, 0.69, 1.03, mats));
    root.add(box(0.1, 0.13, 0.08, PINK_DARK, -0.18, 1.04, 0.7, mats));
    root.add(box(0.1, 0.13, 0.08, PINK_DARK, 0.18, 1.04, 0.7, mats));
    const eyeL = box(0.07, 0.07, 0.04, 0x211516, -0.16, 0.84, 1.015, mats);
    const eyeR = box(0.07, 0.07, 0.04, 0x211516, 0.16, 0.84, 1.015, mats);
    root.add(eyeL, eyeR);
    root.add(box(0.07, 0.07, 0.12, PINK_DARK, 0, 0.63, -0.66, mats));

    const legs = [];
    for (const [lx, lz] of [[-0.27, 0.39], [0.27, 0.39], [-0.27, -0.39], [0.27, -0.39]]) {
      const pivot = new THREE.Group();
      pivot.position.set(lx, 0.45, lz);
      pivot.add(box(0.2, 0.43, 0.2, HOOF, 0, -0.21, 0, mats));
      root.add(pivot);
      legs.push(pivot);
    }
    root.scale.setScalar(1.12);
    root.position.set(x, y, z);
    root.rotation.y = rand() * Math.PI * 2;
    this.scene.add(root);
    this.pigs.push({
      root, head, legs,
      x, z, y,
      angle: rand() * Math.PI * 2,
      targetAngle: rand() * Math.PI * 2,
      timer: 1 + rand() * 3,
      speed: 0.55 + rand() * 0.4,
      phase: rand() * 10,
      moving: true,
    });
  }

  update(dt, daylight) {
    const tint = 0.36 + 0.64 * daylight;
    for (const [color, mat] of Object.entries(this.materials)) {
      const base = new THREE.Color(Number(color));
      mat.color.copy(base).multiplyScalar(0.75 + 0.25 * tint).lerp(new THREE.Color(0x233052), (1 - daylight) * 0.28);
    }
    for (const pig of this.pigs) {
      pig.timer -= dt;
      if (pig.timer <= 0) {
        pig.timer = 2 + Math.random() * 5;
        pig.targetAngle = pig.angle + (Math.random() - 0.5) * Math.PI * 1.6;
        pig.moving = Math.random() > 0.25;
      }
      let diff = ((pig.targetAngle - pig.angle + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
      pig.angle += diff * Math.min(1, dt * 2.5);
      let moved = false;
      if (pig.moving) {
        const nx = pig.x + Math.sin(pig.angle) * pig.speed * dt;
        const nz = pig.z + Math.cos(pig.angle) * pig.speed * dt;
        if (nx > 10 && nx < 118 && nz > 10 && nz < 118) {
          const topY = this.world.topSolidY(Math.floor(nx), Math.floor(nz));
          const top = this.world.getBlock(Math.floor(nx), topY - 1, Math.floor(nz));
          if ((top === BLOCK.GRASS || top === BLOCK.SAND || top === BLOCK.SNOW) && Math.abs(topY - pig.y) < 1.1) {
            pig.x = nx;
            pig.z = nz;
            pig.y = topY;
            moved = true;
          } else {
            pig.targetAngle = pig.angle + Math.PI * (0.6 + Math.random() * 0.8);
          }
        } else {
          pig.targetAngle = pig.angle + Math.PI;
        }
      }
      pig.phase += dt * (moved ? 8 : 0);
      const swing = moved ? Math.sin(pig.phase) * 0.55 : 0;
      pig.legs[0].rotation.x = swing;
      pig.legs[1].rotation.x = -swing;
      pig.legs[2].rotation.x = -swing;
      pig.legs[3].rotation.x = swing;
      pig.head.rotation.x = moved ? Math.sin(pig.phase * 0.5) * 0.06 : 0;
      pig.root.position.set(pig.x, pig.y + (moved ? Math.abs(Math.sin(pig.phase)) * 0.03 : 0), pig.z);
      pig.root.rotation.y = pig.angle;
    }
  }

  get count() { return this.pigs.length; }
}

