:root {
  --ink: #17251f;
  --cream: #fff8e8;
  --leaf: #78c24e;
  --leaf-dark: #3e7c31;
  --gold: #ffd45e;
  --sky: #79c7f1;
  --glass: rgba(12, 24, 25, 0.56);
  --glass-strong: rgba(10, 20, 22, 0.82);
  --line: rgba(255, 255, 255, 0.16);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #79c7f1;
  color: var(--cream);
  font-family: "Trebuchet MS", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; touch-action: none; }

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }

#game-shell { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

.hidden { display: none !important; }

/* ------------------------------------------------------------------ HUD */
#hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  padding: calc(10px + var(--safe-t)) calc(12px + var(--safe-r)) calc(10px + var(--safe-b)) calc(12px + var(--safe-l));
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}
#hud button { pointer-events: auto; }

#hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.identity { display: flex; flex-direction: column; gap: 3px; }
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: "Arial Black", "Arial Bold", "Trebuchet MS", sans-serif;
  font-weight: 900;
  font-size: clamp(18px, 2.2vw, 30px);
  letter-spacing: 1.2px;
  line-height: 1;
  color: var(--cream);
  text-shadow: 0 2px 0 #244b2c, 0 4px 8px rgba(0, 0, 0, 0.35);
}
.brand-isle { color: var(--gold); margin-left: 6px; }
.brand-cube {
  width: 18px; height: 18px;
  border-radius: 3px;
  background:
    linear-gradient(135deg, transparent 0 47%, rgba(255,255,255,.35) 47% 53%, transparent 53%),
    linear-gradient(145deg, #99db68 0 52%, #5aa63d 52%);
  box-shadow: inset 0 0 0 2px rgba(18, 56, 25, 0.35), 0 2px 0 #2d5c34;
  transform: rotate(8deg);
}
.brand-cube::after {
  content: "";
  display: block;
  width: 8px; height: 8px;
  margin: 5px 0 0 5px;
  background: rgba(255,255,255,.2);
}
.world-meta {
  display: flex;
  gap: 7px;
  align-items: center;
  font-size: clamp(9px, 1vw, 12px);
  font-weight: 800;
  letter-spacing: 1.4px;
  color: rgba(255, 255, 255, 0.85);
}
.meta-dot { opacity: 0.45; }

.top-actions { display: flex; gap: 6px; }
.icon-btn {
  width: clamp(38px, 4.6vw, 46px);
  height: clamp(38px, 4.6vw, 46px);
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--glass);
  border: 1px solid var(--line);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.18);
  transition: transform 0.12s, background 0.12s;
}
.icon-btn:hover { background: rgba(32, 52, 48, 0.7); }
.icon-btn:active { transform: translateY(2px); box-shadow: none; }
.icon-btn svg { width: 58%; height: 58%; fill: #fff; opacity: 0.92; }
.icon-btn.muted svg { opacity: 0.35; }

/* -------------------------------------------------------------- goals */
.goal-card {
  position: absolute;
  top: calc(82px + var(--safe-t));
  left: calc(12px + var(--safe-l));
  width: min(280px, 62vw);
  padding: 10px 12px 11px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(14, 29, 27, 0.72), rgba(14, 29, 27, 0.5));
  border: 1px solid var(--line);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  box-shadow: 0 3px 0 rgba(0,0,0,.14);
  transition: transform 0.3s, opacity 0.3s;
}
.goal-card.pop { animation: goalPop 0.55s ease; }
.goal-top {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.6px;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 3px;
}
#goalKicker { color: var(--gold); }
#goalProgress { color: rgba(255, 255, 255, 0.82); }
#goalLabel { font-size: clamp(12px, 1.2vw, 15px); font-weight: 800; letter-spacing: 0.3px; }
.goal-track {
  margin-top: 7px;
  height: 6px;
  border-radius: 99px;
  background: rgba(0, 0, 0, 0.3);
  overflow: hidden;
}
#goalFill {
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, #8be05b, #ffd45e);
  box-shadow: 0 0 10px rgba(255, 212, 94, 0.4);
  transition: width 0.3s ease;
}
@keyframes goalPop {
  0% { transform: scale(1); }
  30% { transform: scale(1.04); }
  100% { transform: scale(1); }
}

/* ----------------------------------------------------------- crosshair */
#crosshair {
  position: absolute;
  left: 50%; top: 50%;
  width: 28px; height: 28px;
  transform: translate(-50%, -50%);
  opacity: 0.8;
  pointer-events: none;
}
#crosshair span {
  position: absolute;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.9);
  border-radius: 1px;
}
#crosshair span:nth-child(1) { left: 50%; top: 2px; width: 2px; height: 8px; transform: translateX(-50%); }
#crosshair span:nth-child(2) { top: 50%; left: 2px; height: 2px; width: 8px; transform: translateY(-50%); }
#crosshair i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; background: #fff; border-radius: 50%; transform: translate(-50%, -50%); box-shadow: 0 0 2px #000; }
#crosshair.mining span, #crosshair.mining i { background: var(--gold); }

/* --------------------------------------------------------------- toast */
#toast {
  position: absolute;
  left: 50%;
  top: 21%;
  transform: translate(-50%, -10px);
  padding: 10px 18px;
  border-radius: 12px;
  background: rgba(12, 24, 25, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(10px);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.5px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.25s;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.18);
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast.gold { border-color: rgba(255, 212, 94, 0.6); color: var(--gold); }

#waterTint {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(20, 84, 155, 0.32), rgba(10, 50, 96, 0.52));
  opacity: 0;
  transition: opacity 0.25s;
  pointer-events: none;
}

/* ------------------------------------------------------------- hotbar */
#hotbarWrap {
  position: absolute;
  left: 50%;
  bottom: calc(9px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px;
  border-radius: 14px;
  background: rgba(10, 22, 24, 0.66);
  border: 1px solid var(--line);
  backdrop-filter: blur(11px);
  -webkit-backdrop-filter: blur(11px);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255,255,255,.07);
  pointer-events: auto;
  max-width: calc(100vw - 8px);
}
#hotbar { display: flex; gap: clamp(2px, 0.55vw, 5px); }
.slot {
  position: relative;
  width: clamp(29px, 7.4vw, 48px);
  height: clamp(35px, 8.6vw, 54px);
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  border: 2px solid transparent;
  transition: transform 0.12s ease, border-color 0.12s, background 0.12s;
}
.slot:hover { background: rgba(255,255,255,.12); }
.slot img { width: 78%; height: 78%; image-rendering: pixelated; filter: drop-shadow(0 2px 2px rgba(0,0,0,.35)); }
.slot .num {
  position: absolute;
  left: 3px; top: 1px;
  font-size: 8px;
  font-weight: 900;
  opacity: 0.5;
  text-shadow: 0 1px 2px #000;
}
.slot.selected {
  background: rgba(255, 212, 94, 0.2);
  border-color: var(--gold);
  transform: translateY(-5px);
  box-shadow: 0 0 0 1px rgba(0,0,0,.22), 0 5px 0 rgba(0,0,0,.18);
}
.palette-btn {
  width: clamp(34px, 8.6vw, 54px);
  height: clamp(35px, 8.6vw, 54px);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.17);
  display: grid;
  place-items: center;
  transition: transform .12s, background .12s;
}
.palette-btn:hover { background: rgba(255, 212, 94, 0.24); }
.palette-btn:active { transform: scale(.94); }
.palette-btn svg { width: 46%; height: 46%; fill: #fff; opacity: .9; }

.block-label {
  position: absolute;
  left: 50%;
  bottom: calc(77px + var(--safe-b));
  transform: translateX(-50%) translateY(4px);
  padding: 5px 10px;
  border-radius: 7px;
  background: rgba(10, 22, 24, 0.7);
  border: 1px solid rgba(255,255,255,.12);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.4px;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .2s, transform .2s;
}
.block-label.show { opacity: 1; transform: translateX(-50%) translateY(0); }

#desktopHint {
  position: absolute;
  left: calc(12px + var(--safe-l));
  bottom: calc(15px + var(--safe-b));
  display: none;
  flex-direction: column;
  gap: 3px;
  font-size: 10px;
  letter-spacing: .4px;
  color: rgba(255,255,255,.62);
}
#desktopHint b { color: rgba(255,255,255,.95); font-size: 9px; letter-spacing: 1px; }
body.desktop #desktopHint { display: flex; }

/* --------------------------------------------------------- touch UI */
#touch-controls { position: absolute; inset: 0; pointer-events: none; }
body.touch #touch-controls:not(.hidden) { display: block; }
#joystick {
  position: absolute;
  left: calc(16px + var(--safe-l));
  bottom: calc(82px + var(--safe-b));
  width: clamp(102px, 26vw, 136px);
  height: clamp(102px, 26vw, 136px);
  pointer-events: auto;
  touch-action: none;
}
#joystickBase {
  width: 100%; height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(255,255,255,.12), rgba(7,18,21,.26));
  border: 2px solid rgba(255, 255, 255, 0.28);
  box-shadow: inset 0 0 20px rgba(0,0,0,.18), 0 4px 18px rgba(0,0,0,.15);
  display: grid;
  place-items: center;
  backdrop-filter: blur(2px);
}
#joystickBase::before, #joystickBase::after {
  content: "";
  position: absolute;
  background: rgba(255,255,255,.13);
  border-radius: 2px;
}
#joystickBase::before { width: 44%; height: 1px; }
#joystickBase::after { height: 44%; width: 1px; }
#joystickKnob {
  width: 46%;
  height: 46%;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #fdfaf0, #cbd6c2 64%, #7c9278);
  border: 2px solid rgba(255,255,255,.6);
  box-shadow: 0 5px 12px rgba(0,0,0,.3), inset 0 -4px 8px rgba(30,50,30,.18);
  transition: transform .08s;
}
#joystick.active #joystickKnob { transition: none; }
.touch-btn {
  position: absolute;
  width: clamp(58px, 15.5vw, 76px);
  height: clamp(58px, 15.5vw, 76px);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  pointer-events: auto;
  touch-action: none;
  background: radial-gradient(circle at 38% 30%, rgba(255,255,255,.32), rgba(15,31,33,.58) 70%);
  border: 2px solid rgba(255,255,255,.35);
  box-shadow: 0 5px 0 rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.25);
  backdrop-filter: blur(5px);
  transition: transform .09s, filter .09s;
}
.touch-btn:active, .touch-btn.pressed { transform: translateY(3px) scale(.97); filter: brightness(1.2); box-shadow: 0 2px 0 rgba(0,0,0,.22); }
.touch-btn svg { width: 34%; height: 34%; fill: #fff; filter: drop-shadow(0 1px 2px rgba(0,0,0,.4)); }
.touch-btn span { font-size: 7px; font-weight: 900; letter-spacing: 1px; opacity: .82; }
.touch-btn.mine {
  right: calc(14px + var(--safe-r));
  bottom: calc(86px + var(--safe-b));
  width: clamp(66px, 17vw, 84px);
  height: clamp(66px, 17vw, 84px);
  background: radial-gradient(circle at 38% 30%, rgba(255, 232, 173, .42), rgba(72, 52, 16, .62) 70%);
}
.touch-btn.place {
  right: calc(84px + var(--safe-r));
  bottom: calc(94px + var(--safe-b));
  width: clamp(54px, 13.5vw, 68px);
  height: clamp(54px, 13.5vw, 68px);
  background: radial-gradient(circle at 38% 30%, rgba(193, 239, 255, .35), rgba(16, 45, 52, .6) 70%);
}
.touch-btn.jump {
  right: calc(36px + var(--safe-r));
  bottom: calc(167px + var(--safe-b));
  width: clamp(52px, 13vw, 66px);
  height: clamp(52px, 13vw, 66px);
}
.touch-btn.mine.pressed { animation: minePulse .7s infinite; }
@keyframes minePulse {
  0%, 100% { box-shadow: 0 2px 0 rgba(0,0,0,.22), 0 0 0 0 rgba(255,212,94,.4); }
  50% { box-shadow: 0 2px 0 rgba(0,0,0,.22), 0 0 0 8px rgba(255,212,94,0); }
}

/* --------------------------------------------------------------- screens */
.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
}
#loading {
  z-index: 60;
  background: radial-gradient(circle at 50% 42%, #2f6d4a 0%, #14352e 55%, #0a1e20 100%);
}
.loading-inner { text-align: center; width: min(360px, 78vw); }
.loading-cube {
  width: 48px; height: 48px;
  margin: 0 auto 22px;
  background:
    linear-gradient(90deg, transparent 0 47%, rgba(0,0,0,.16) 47% 53%, transparent 53%),
    linear-gradient(0deg, transparent 0 47%, rgba(0,0,0,.16) 47% 53%, transparent 53%),
    linear-gradient(145deg, #9ddf69, #5ca73f);
  border: 3px solid #2b5228;
  box-shadow: inset -8px -8px 0 rgba(0,0,0,.14), 0 8px 0 #1b3f2a, 0 14px 24px rgba(0,0,0,.3);
  animation: cubeHop 1.4s ease-in-out infinite;
}
@keyframes cubeHop {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-9px) rotate(2deg); }
}
.loading-inner h2 { font-family: "Arial Black", sans-serif; font-size: 16px; letter-spacing: 2.4px; margin: 0 0 8px; }
#loadingText { margin: 0 0 18px; font-size: 12px; color: rgba(255,255,255,.55); }
.loading-track { height: 10px; border-radius: 99px; background: rgba(0,0,0,.35); overflow: hidden; border: 1px solid rgba(255,255,255,.1); }
#loadingFill { height: 100%; width: 0%; background: linear-gradient(90deg, #8ee05d, #ffd45e); transition: width .18s ease; }

/* ----------------------------------------------------------- start screen */
#startScreen {
  z-index: 25;
  align-items: stretch;
  justify-content: flex-start;
  background: radial-gradient(ellipse at 72% 42%, rgba(0,0,0,0) 0%, rgba(6,22,20,.12) 45%, rgba(6,22,20,.55) 100%);
}
.start-vignette {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(7,22,20,.72) 0%, rgba(7,22,20,.45) 38%, rgba(7,22,20,0) 68%),
              linear-gradient(0deg, rgba(7,22,20,.55) 0%, transparent 35%);
}
.start-inner {
  position: relative;
  z-index: 2;
  align-self: center;
  margin-left: clamp(20px, 7vw, 100px);
  width: min(540px, 84vw);
  padding-bottom: 5vh;
}
.eyebrow { margin: 0 0 10px; font-size: 10px; font-weight: 900; letter-spacing: 3.2px; color: var(--gold); }
.game-title {
  margin: 0;
  font-family: "Arial Black", "Trebuchet MS", sans-serif;
  font-weight: 900;
  font-size: clamp(58px, 9.6vw, 112px);
  line-height: 0.82;
  letter-spacing: -2px;
  color: #fff8e4;
  text-shadow:
    0 3px 0 #2d4e30,
    0 6px 0 #1b3625,
    0 12px 24px rgba(0,0,0,.45);
}
.game-title span {
  display: inline-block;
  margin-left: 0.06em;
  color: #8fe05d;
  text-shadow:
    0 3px 0 #356d2e,
    0 6px 0 #1e461f,
    0 12px 24px rgba(0,0,0,.45);
}
.tagline {
  margin: 22px 0 26px;
  max-width: 380px;
  font-size: clamp(14px, 1.5vw, 18px);
  line-height: 1.45;
  color: rgba(255,255,255,.8);
  font-weight: 600;
}
.play-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 14px;
  min-width: 220px;
  padding: 15px 30px 17px;
  border-radius: 12px;
  background: linear-gradient(180deg, #99e265, #6cbb43);
  border: 2px solid #d9f7b0;
  color: #143418;
  font-family: "Arial Black", sans-serif;
  font-weight: 900;
  font-size: clamp(19px, 2.2vw, 24px);
  letter-spacing: 2.4px;
  box-shadow: 0 6px 0 #3b732e, 0 14px 28px rgba(0,0,0,.3), inset 0 2px 0 rgba(255,255,255,.45);
  transition: transform .12s, box-shadow .12s, filter .12s;
}
.play-btn:hover { filter: brightness(1.07); transform: translateY(-1px); box-shadow: 0 7px 0 #3b732e, 0 18px 30px rgba(0,0,0,.32), inset 0 2px 0 rgba(255,255,255,.45); }
.play-btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #3b732e, 0 8px 16px rgba(0,0,0,.28), inset 0 2px 0 rgba(255,255,255,.3); }
.play-icon {
  width: 0; height: 0;
  border-left: 14px solid #143418;
  border-top: 9px solid transparent;
  border-bottom: 9px solid transparent;
  margin-left: 2px;
}
.control-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 25px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .7px;
  color: rgba(255,255,255,.82);
  background: rgba(9, 23, 21, 0.42);
  border: 1px solid rgba(255,255,255,.13);
  backdrop-filter: blur(4px);
}
.chip-icon { font-style: normal; font-size: 13px; opacity: .9; }
body.touch .desktop-chip { display: none; }
body.desktop .touch-chip { display: none; }
.save-note { min-height: 16px; margin: 18px 0 0; font-size: 10px; letter-spacing: 1.2px; color: rgba(255,255,255,.48); }
.start-footer {
  position: absolute;
  left: 0; right: 0;
  bottom: calc(18px + var(--safe-b));
  text-align: center;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2px;
  color: rgba(255,255,255,.4);
  z-index: 2;
}
.title-blocks { position: absolute; inset: 0; pointer-events: none; z-index: -1; }
.title-blocks img {
  position: absolute;
  width: clamp(42px, 5.5vw, 70px);
  image-rendering: pixelated;
  filter: drop-shadow(0 8px 10px rgba(0,0,0,.35));
  animation: floaty 6s ease-in-out infinite;
  opacity: .92;
}
@keyframes floaty {
  0%, 100% { transform: translateY(0) rotate(-4deg); }
  50% { transform: translateY(-12px) rotate(5deg); }
}

/* ---------------------------------------------------------------- panels */
#pauseScreen, #paletteScreen, #helpScreen {
  background: rgba(5, 14, 14, 0.55);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  z-index: 40;
  padding: 20px;
  overflow-y: auto;
}
.panel {
  width: min(430px, 92vw);
  max-height: min(700px, 92vh);
  overflow-y: auto;
  padding: 26px;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(26, 46, 38, 0.97), rgba(12, 27, 25, 0.98));
  border: 1px solid rgba(255,255,255,.16);
  box-shadow: 0 24px 60px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.12);
  text-align: center;
}
.panel-head { margin-bottom: 20px; }
.panel-head .eyebrow { margin-bottom: 6px; }
.panel h2 {
  margin: 0;
  font-family: "Arial Black", sans-serif;
  font-size: clamp(26px, 5vw, 38px);
  letter-spacing: 1px;
  color: #fff8e4;
  text-shadow: 0 3px 0 rgba(0,0,0,.3);
}
.panel-sub { margin: 8px 0 0; font-size: 11px; color: rgba(255,255,255,.55); }
.menu-btn {
  display: block;
  width: 100%;
  margin: 8px 0;
  padding: 13px 16px;
  border-radius: 10px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.13);
  font-weight: 900;
  font-size: 13px;
  letter-spacing: 1.4px;
  color: #fff;
  transition: background .12s, transform .12s;
}
.menu-btn:hover { background: rgba(255,255,255,.15); }
.menu-btn:active { transform: scale(.985); }
.menu-btn.primary { background: linear-gradient(180deg, #91db5f, #6bb643); border-color: #c9ee9d; color: #143418; box-shadow: 0 4px 0 #3f7630; }
.menu-btn.primary:hover { filter: brightness(1.06); }
.menu-btn.danger { color: #ffb4a8; border-color: rgba(255, 120, 100, .3); background: rgba(120, 40, 32, .22); }
.menu-btn.danger.confirm { background: #ad4034; color: #fff; border-color: #ff9d8f; }
.panel-note { min-height: 14px; margin: 8px 0 0; font-size: 10px; color: rgba(255,255,255,.5); letter-spacing: .7px; }
.panel-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid rgba(255,255,255,.1);
}
.panel-stats div { display: flex; flex-direction: column; gap: 2px; }
.panel-stats b { font-family: "Arial Black", sans-serif; font-size: 22px; color: var(--gold); }
.panel-stats span { font-size: 8px; letter-spacing: 1.2px; color: rgba(255,255,255,.45); }
.seed-note { margin: 16px 0 0; font-size: 8px; letter-spacing: 1.6px; color: rgba(255,255,255,.28); }
.seed-note b { color: rgba(255,255,255,.5); }

/* ------------------------------------------------------------- library */
.library-panel { width: min(520px, 94vw); }
.palette-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin: 8px 0 18px;
}
.palette-item {
  position: relative;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  transition: background .12s, transform .12s, border-color .12s;
}
.palette-item:hover { background: rgba(255,255,255,.14); transform: translateY(-2px); }
.palette-item.active { border-color: var(--gold); background: rgba(255,212,94,.13); }
.palette-item img { width: 66%; height: 66%; image-rendering: pixelated; filter: drop-shadow(0 2px 3px rgba(0,0,0,.35)); }
.palette-item span {
  position: absolute;
  left: 4px; right: 4px; bottom: 4px;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .6px;
  color: rgba(255,255,255,.58);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.palette-item.active span { color: var(--gold); }

/* ---------------------------------------------------------------- help */
.help-panel { width: min(540px, 94vw); text-align: left; }
.help-panel .panel-head { text-align: center; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.help-item {
  padding: 13px;
  border-radius: 12px;
  background: rgba(255,255,255,.055);
  border: 1px solid rgba(255,255,255,.09);
}
.help-emoji { font-size: 19px; display: block; margin-bottom: 5px; }
.help-item b { font-size: 10px; letter-spacing: 1.4px; color: var(--gold); }
.help-item p { margin: 5px 0 0; font-size: 11px; line-height: 1.45; color: rgba(255,255,255,.62); }
.help-tip { font-size: 10px; line-height: 1.5; color: rgba(255,255,255,.45); margin: 15px 0; text-align: center; }
.help-panel .menu-btn { text-align: center; }

#fade {
  position: absolute;
  inset: 0;
  background: #0a1a18;
  opacity: 0;
  pointer-events: none;
  transition: opacity .28s;
  z-index: 55;
}
#fade.on { opacity: 1; pointer-events: auto; }

/* ------------------------------------------------------------ responsive */
@media (max-width: 760px) {
  #hud { padding: calc(9px + var(--safe-t)) calc(9px + var(--safe-r)) calc(8px + var(--safe-b)) calc(9px + var(--safe-l)); }
  .brand { font-size: 18px; gap: 6px; }
  .brand-cube { width: 15px; height: 15px; }
  .brand-cube::after { width: 6px; height: 6px; margin: 4px 0 0 4px; }
  .world-meta { font-size: 8px; letter-spacing: 1px; }
  .goal-card { top: calc(72px + var(--safe-t)); left: calc(9px + var(--safe-l)); width: min(230px, 64vw); padding: 8px 10px 9px; }
  #goalLabel { font-size: 12px; }
  .goal-top { font-size: 8px; }
  .block-label { bottom: calc(69px + var(--safe-b)); }
  #toast { top: 17%; font-size: 11px; padding: 9px 14px; max-width: 86vw; white-space: normal; text-align: center; }
  #hotbarWrap { padding: 4px; gap: 4px; border-radius: 11px; }
  .slot .num { display: none; }
  .start-inner { margin: 0 auto; width: 88vw; text-align: center; align-self: flex-end; padding-bottom: 15vh; }
  #startScreen { align-items: flex-end; }
  .start-vignette { background: linear-gradient(0deg, rgba(7,22,20,.82) 0%, rgba(7,22,20,.52) 44%, rgba(7,22,20,.1) 75%, rgba(7,22,20,.25) 100%); }
  .eyebrow { font-size: 8px; letter-spacing: 2.6px; }
  .game-title { font-size: clamp(56px, 17vw, 82px); }
  .tagline { margin: 18px auto 22px; font-size: 13px; max-width: 300px; }
  .play-btn { min-width: 210px; justify-content: center; padding: 14px 26px 16px; font-size: 19px; }
  .control-chips { justify-content: center; gap: 6px; margin-top: 20px; }
  .chip { font-size: 8px; padding: 6px 9px; letter-spacing: .4px; }
  .chip-icon { font-size: 11px; }
  .start-footer { font-size: 7px; letter-spacing: 1.3px; }
  .title-blocks img { opacity: .7; }
  .panel { padding: 20px 18px; border-radius: 16px; max-height: 88vh; }
  .palette-grid { grid-template-columns: repeat(4, 1fr); }
}

@media (max-height: 560px) and (orientation: landscape) {
  #hud-top { align-items: flex-start; }
  .goal-card { top: calc(62px + var(--safe-t)); width: 210px; padding: 6px 9px; }
  #goalLabel { font-size: 10px; }
  .goal-track { margin-top: 4px; height: 4px; }
  #hotbarWrap { bottom: calc(6px + var(--safe-b)); transform: translateX(-50%) scale(.92); transform-origin: bottom center; }
  #joystick { bottom: calc(63px + var(--safe-b)); width: 92px; height: 92px; }
  .touch-btn.mine { bottom: calc(62px + var(--safe-b)); width: 58px; height: 58px; }
