const QUESTS = [
  {
    kicker: 'GATHER', label: 'Chop 3 oak logs', target: 3,
    value: () => stats.logs,
  },
  {
    kicker: 'BUILD', label: 'Place 12 blocks', target: 12,
    value: () => stats.placed,
