import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
mkdirSync('screenshots', { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 2,
});
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
await page.waitForTimeout(600);
await page.screenshot({ path: 'screenshots/mobile-start.jpg', type: 'jpeg', quality: 80 });
console.log('menu', await page.evaluate(() => ({ state: window.__BLOCK_ISLE__.state, touch: document.body.classList.contains('touch'), save: !!document.getElementById('startSaveNote').textContent })));

await page.locator('#playBtn').tap();
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/mobile-game.jpg', type: 'jpeg', quality: 80 });
console.log('playing', await page.evaluate(() => ({ state: window.__BLOCK_ISLE__.state, pos: window.__BLOCK_ISLE__.player.pos.toArray(), touchControls: getComputedStyle(document.getElementById('touch-controls')).display })));

const cdp = await context.newCDPSession(page);
const before = await page.evaluate(() => window.__BLOCK_ISLE__.player.pos.toArray());
const joy = await page.locator('#joystickBase').boundingBox();
const cx = joy.x + joy.width / 2;
const cy = joy.y + joy.height / 2;
await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: cx, y: cy, id: 1 }] });
await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: cx + 10, y: cy - 45, id: 1 }] });
await page.waitForTimeout(1200);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(200);
const after = await page.evaluate(() => window.__BLOCK_ISLE__.player.pos.toArray());
console.log('joystick moved', before, '->', after);

// Touch look drag.
const yaw0 = await page.evaluate(() => window.__BLOCK_ISLE__.player.yaw);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 300, y: 300, id: 2 }] });
await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 240, y: 300, id: 2 }] });
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(200);
const yaw1 = await page.evaluate(() => window.__BLOCK_ISLE__.player.yaw);
console.log('yaw changed', yaw0, '->', yaw1);

// Aim down and hold the mine button.
await page.evaluate(() => window.__BLOCK_ISLE__.setLook(window.__BLOCK_ISLE__.player.yaw, -1.15));
await page.waitForTimeout(100);
const target = await page.evaluate(() => window.__BLOCK_ISLE__.target);
console.log('target', target);
const minedBefore = await page.evaluate(() => window.__BLOCK_ISLE__.stats.mined);
const mine = await page.locator('#mineBtn').boundingBox();
const mx = mine.x + mine.width / 2;
const my = mine.y + mine.height / 2;
await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: mx, y: my, id: 3 }] });
await page.waitForTimeout(900);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
const minedAfter = await page.evaluate(() => window.__BLOCK_ISLE__.stats.mined);
console.log('mined', minedBefore, '->', minedAfter);
await page.waitForTimeout(300);
await page.screenshot({ path: 'screenshots/mobile-mined.jpg', type: 'jpeg', quality: 80 });

// Place with the active block after aiming at the ground.
const placedBefore = await page.evaluate(() => window.__BLOCK_ISLE__.stats.placed);
const placed = await page.evaluate(() => window.__BLOCK_ISLE__.placeBlock());
const placedAfter = await page.evaluate(() => window.__BLOCK_ISLE__.stats.placed);
console.log('place', placed, placedBefore, '->', placedAfter);

console.log('state', await page.evaluate(() => ({ state: window.__BLOCK_ISLE__.state, pos: window.__BLOCK_ISLE__.player.pos.toArray(), errors: [] })));
console.log('errors', errors);
await browser.close();

