input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];

async function makePage(options) {
  const context = await browser.newContext(options);
  const page = await context.newPage();
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
  return { context, page };
}

// Desktop / tablet viewport check.
const { context: desktop, page } = await makePage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/desktop-start.jpg', type: 'jpeg', quality: 82 });
const startInfo = await page.evaluate(() => ({
  state: window.__BLOCK_ISLE__.state,
  seed: window.__BLOCK_ISLE__.world.seed,
  save: localStorage.getItem('blockisle.save.v1') !== null,
  touch: document.body.classList.contains('touch'),
}));
console.log('desktop start', startInfo);

await page.locator('#playBtn').click();
await page.waitForTimeout(800);
await page.screenshot({ path: 'screenshots/desktop-game.jpg', type: 'jpeg', quality: 82 });
console.log('desktop play', await page.evaluate(() => ({
  state: window.__BLOCK_ISLE__.state,
  hand: window.__BLOCK_ISLE__.player.pos.toArray(),
  hotbar: [...document.querySelectorAll('#hotbar .slot')].length,
  render: window.__BLOCK_ISLE__.renderInfo(),
})));

const fps = await page.evaluate(async () => {
  let frames = 0;
  const start = performance.now();
  await new Promise((resolve) => {
    const tick = () => {
      frames++;
      if (performance.now() - start > 2000) resolve();
      else requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  return Math.round((frames * 1000) / (performance.now() - start));
});
console.log('fps (software renderer)', fps);

// Night visual.
await page.evaluate(() => window.__BLOCK_ISLE__.setTime(0.92));
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/desktop-night.jpg', type: 'jpeg', quality: 82 });
console.log('night time', await page.evaluate(() => document.getElementById('clock').textContent));
await page.evaluate(() => window.__BLOCK_ISLE__.setTime(0.34));

// Goal logic.
const goal = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.stats.logs = 3;
  b.updateGoal(true);
  return { questIndex: b.stats.questIndex, label: document.getElementById('goalLabel').textContent };
});
console.log('goal after 3 logs', goal);

// Break a real block and save.
const broken = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.stats.logs = 0;
  b.stats.questIndex = 0;
  b.updateGoal(false);
  b.setLook(b.player.yaw, -1.2);
  const t = b.target;
  if (!t) return { ok: false };
  const before = b.world.getBlock(t.x, t.y, t.z);
  const ok = b.breakBlock(t);
  const after = b.world.getBlock(t.x, t.y, t.z);
  b.saveGame();
  return { ok, before, after, mined: b.stats.mined, pos: [t.x, t.y, t.z] };
});
console.log('break real block', broken);

// Place a block and save.
const placed = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.player.pitch = -0.55;
  const ok = b.placeBlock();
  b.saveGame();
  return { ok, placed: b.stats.placed, edits: b.world.edits.size };
});
console.log('place block', placed);

await page.reload();
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
console.log('after reload', await page.evaluate(() => ({
  state: window.__BLOCK_ISLE__.state,
  seed: window.__BLOCK_ISLE__.world.seed,
  stats: window.__BLOCK_ISLE__.stats,
  edits: window.__BLOCK_ISLE__.world.edits.size,
  saveNote: document.getElementById('startSaveNote').textContent,
  playLabel: document.getElementById('playLabel').textContent,
})));
await page.screenshot({ path: 'screenshots/desktop-continue.jpg', type: 'jpeg', quality: 82 });

await desktop.close();

// Tablet touch layout.
const { context: tablet, page: tp } = await makePage({
  viewport: { width: 1024, height: 768 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 1,
});
await tp.waitForTimeout(700);
await tp.screenshot({ path: 'screenshots/tablet-start.jpg', type: 'jpeg', quality: 82 });
await tp.locator('#playBtn').tap();
await tp.waitForTimeout(900);
await tp.screenshot({ path: 'screenshots/tablet-game.jpg', type: 'jpeg', quality: 82 });
console.log('tablet', await tp.evaluate(() => ({
  state: window.__BLOCK_ISLE__.state,
  touch: document.body.classList.contains('touch'),
  joystick: getComputedStyle(document.getElementById('joystick')).display,
  hotbar: [...document.querySelectorAll('#hotbar .slot')].length,
  touchControls: getComputedStyle(document.getElementById('touch-controls')).display,
})));
await tablet.close();

console.log('errors', errors);
await browser.close();

