import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
await page.waitForTimeout(700);
await page.locator('#playBtn').click();
await page.waitForTimeout(800);
await page.screenshot({ path: 'screenshots/desktop-game2.jpg', type: 'jpeg', quality: 82 });
console.log('day', await page.evaluate(() => ({ fps: 0, info: window.__BLOCK_ISLE__.renderInfo() })));
await page.evaluate(() => window.__BLOCK_ISLE__.setTime(0.92));
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/desktop-night2.jpg', type: 'jpeg', quality: 82 });
await page.evaluate(() => window.__BLOCK_ISLE__.setTime(0.34));
// Build a small tower in front of the player to verify edits and visuals.
await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  const p = b.player;
  const bx = Math.floor(p.pos.x) + 4;
  const bz = Math.floor(p.pos.z);
  const by = Math.floor(p.pos.y);
  for (let y = 0; y < 5; y++) {
    b.world.setBlock(bx, by + y, bz, 8);
    b.world.setBlock(bx + 1, by + y, bz, 9);
  }
  b.world.setBlock(bx, by + 5, bz, 12);
  b.setLook(Math.atan2(-4, 0.2), -0.05);
});
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/desktop-build.jpg', type: 'jpeg', quality: 82 });
console.log('errors', errors);
await browser.close();

import { createRequire } from 'node:module';
