import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];

async function shot(options, prefix) {
  const context = await browser.newContext(options);
  const page = await context.newPage();
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
  await page.waitForTimeout(900);
  await page.screenshot({ path: `screenshots/${prefix}-start.jpg`, type: 'jpeg', quality: 80 });
  await page.locator('#playBtn').click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: `screenshots/${prefix}-game.jpg`, type: 'jpeg', quality: 80 });
  const info = await page.evaluate(() => ({
    state: window.__BLOCK_ISLE__.state,
    touch: document.body.classList.contains('touch'),
    info: window.__BLOCK_ISLE__.renderInfo(),
    toast: document.getElementById('toast').textContent,
  }));
  console.log(prefix, info);
  await context.close();
}

await shot({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 }, 'final-mobile');
await shot({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 }, 'final-desktop');
