import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1024, height: 640 } });
const page = await context.newPage();
await page.goto('http://localhost:3002');
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
await page.locator('#playBtn').click();
await page.waitForTimeout(1000);
const spot = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  const w = b.world;
  for (let z = 4; z < 124; z++) {
    for (let x = 4; x < 124; x++) {
      const h = w.columnHeight(x, z);
      const top = w.getBlock(x, h, z);
      if (h !== 14 || top !== 5) continue;
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx * 5;
        const nz = z + dz * 5;
        if (nx < 0 || nz < 0 || nx > 127 || nz > 127) continue;
        if (w.getBlock(nx, 13, nz) === 13) {
          b.teleport(x + 0.5 + dx * 1.5, h + 1.01, z + 0.5 + dz * 1.5);
          b.setLook(Math.atan2(dx, dz), -0.18);
          return { x, z, h, dx, dz, top };
        }
      }
    }
  }
  return null;
});
console.log('shore spot', spot);
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/shoreline.jpg', type: 'jpeg', quality: 82 });
await page.evaluate(() => window.__BLOCK_ISLE__.setLook(window.__BLOCK_ISLE__.player.yaw, -0.55));
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/shoreline-down.jpg', type: 'jpeg', quality: 82 });
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1024, height: 640 } });
const page = await context.newPage();
await page.goto('http://localhost:3002');
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
await page.locator('#playBtn').click();
await page.waitForTimeout(1000);
const spot = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  const w = b.world;
  let best = null;
  for (let z = 5; z < 123; z++) {
    for (let x = 5; x < 123; x++) {
      const h = w.columnHeight(x, z);
      if (h < 16 || h > 22) continue;
      const top = w.getBlock(x, h, z);
      if (top !== 1 && top !== 5) continue;
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        let water = false;
        for (let d = 2; d <= 10; d++) {
          if (w.getBlock(x + dx * d, 13, z + dz * d) === 13) { water = true; break; }
        }
        if (water) {
          const score = h;
          if (!best || score > best.score) best = { x, z, h, dx, dz, score };
        }
      }
    }
  }
  if (!best) return null;
  const inlandX = best.x - best.dx * 7;
  const inlandZ = best.z - best.dz * 7;
  const hh = w.columnHeight(inlandX, inlandZ);
  b.teleport(inlandX + 0.5, Math.max(hh, best.h) + 1.01, inlandZ + 0.5);
  b.setLook(Math.atan2(best.dx, best.dz), -0.22);
  return { ...best, inlandX, inlandZ, hh };
});
console.log('vista', spot);
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/coast-vista.jpg', type: 'jpeg', quality: 84 });
await page.evaluate(() => { const s = window.__BLOCK_ISLE__; s.setTime(0.30); });
await page.waitForTimeout(600);
await page.screenshot({ path: 'screenshots/coast-vista2.jpg', type: 'jpeg', quality: 84 });
await browser.close();

