import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= `:${readFileSync(`${runtime}/display`, 'utf8').trim()}`;
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1024, height: 640 } });
const page = await context.newPage();
await page.goto('http://localhost:3002');
await page.waitForFunction(() => window.__BLOCK_ISLE__?.state === 'menu', null, { timeout: 30000 });
await page.locator('#playBtn').click();
await page.waitForTimeout(1000);
await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.teleport(55.5, 15.01, 12.5);
  b.setLook(-Math.PI / 2, -0.2);
  b.setTime(0.30);
});
await page.waitForTimeout(600);
await page.screenshot({ path: 'screenshots/water-base.jpg', type: 'jpeg', quality: 84 });
const info = await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  const scene = b.world.group.parent;
  const waterMeshes = [];
  b.world.group.traverse((o) => { if (o.isMesh && o.material === b.world.materials.water) waterMeshes.push(o); });
  return {
    waterMeshes: waterMeshes.length,
    oceanY: scene.getObjectByName('ocean').position.y,
    waterMat: {
      transparent: b.world.materials.water.transparent,
      opacity: b.world.materials.water.opacity,
      depthWrite: b.world.materials.water.depthWrite,
      side: b.world.materials.water.side,
    },
    oceanMat: {
      transparent: scene.getObjectByName('ocean').material.transparent,
      depthWrite: scene.getObjectByName('ocean').material.depthWrite,
      color: scene.getObjectByName('ocean').material.color.getHexString(),
      fog: scene.getObjectByName('ocean').material.fog,
    },
    fog: { near: scene.fog.near, far: scene.fog.far },
  };
});
console.log(info);
await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.world.group.traverse((o) => { if (o.isMesh && o.material === b.world.materials.water) o.visible = false; });
});
await page.waitForTimeout(400);
await page.screenshot({ path: 'screenshots/water-no-inworld.jpg', type: 'jpeg', quality: 84 });
await page.evaluate(() => {
  const b = window.__BLOCK_ISLE__;
  b.world.group.traverse((o) => { if (o.isMesh && o.material === b.world.materials.water) o.visible = true; });
  b.world.group.parent.getObjectByName('ocean').visible = false;
});
await page.waitForTimeout(400);
await page.screenshot({ path: 'screenshots/water-no-ocean.jpg', type: 'jpeg', quality: 84 });
await browser.close();

